CREATE OR REPLACE FUNCTION private.validate_accounting_month_close()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$ declare pending_count integer; review_count integer; v_document_count integer:=0; v_accounting_count integer:=0; v_invoice_count integer:=0; v_ticket_count integer:=0; v_supplier_count integer:=0; v_purchases numeric:=0; v_invoice_base numeric:=0; v_invoice_vat numeric:=0; v_sales numeric:=0; v_personal numeric:=0; v_personal_cash numeric:=0; v_operating numeric:=0; v_tax_cash numeric:=0; v_tax_load numeric:=0; v_investment numeric:=0; begin if new.month>date_trunc('month',current_date)::date then raise exception 'MONTH_NOT_READY: No se puede cerrar un mes futuro.' using errcode='P0001'; end if; select count(*) into pending_count from public.invoices i where i.user_id=new.user_id and i.deleted_at is null and i.invoice_date>=new.month and i.invoice_date<(new.month+interval '1 month')::date and i.document_type='delivery_note' and i.document_status<>'linked'; if pending_count>0 then raise exception 'MONTH_NOT_READY: Hay % albarán(es) pendiente(s) de factura.',pending_count using errcode='P0001'; end if; select count(*) into review_count from public.invoices i where i.user_id=new.user_id and i.deleted_at is null and i.invoice_date>=new.month and i.invoice_date<(new.month+interval '1 month')::date and i.document_status<>'linked' and i.document_type='invoice' and (nullif(btrim(coalesce(i.invoice_number,'')),'') is null or (i.base_amount is null and i.vat_amount is null)); if review_count>0 then raise exception 'MONTH_NOT_READY: Hay % factura(s) pendiente(s) de revisión.',review_count using errcode='P0001'; end if; select count(*)::int,count(*) filter(where i.document_type<>'delivery_note' and i.document_status<>'linked')::int,count(*) filter(where i.document_type='invoice' and i.document_status<>'linked')::int,count(*) filter(where i.document_type='ticket' and i.document_status<>'linked')::int,count(distinct lower(btrim(i.supplier))) filter(where i.document_type<>'delivery_note' and i.document_status<>'linked' and nullif(btrim(i.supplier),'') is not null)::int,coalesce(sum(i.total) filter(where i.document_type<>'delivery_note' and i.document_status<>'linked'),0),coalesce(sum(i.base_amount) filter(where i.document_type='invoice' and i.document_status<>'linked'),0),coalesce(sum(i.vat_amount) filter(where i.document_type='invoice' and i.document_status<>'linked'),0) into v_document_count,v_accounting_count,v_invoice_count,v_ticket_count,v_supplier_count,v_purchases,v_invoice_base,v_invoice_vat from public.invoices i where i.user_id=new.user_id and i.deleted_at is null and i.invoice_date>=new.month and i.invoice_date<(new.month+interval '1 month')::date; select coalesce(sum(m.amount) filter(where m.move_type='ingreso'),0),coalesce(sum(m.amount) filter(where m.move_type='personal'),0),coalesce(sum(m.amount) filter(where m.move_type='gasto' and coalesce(m.expense_kind,'operating')='operating'),0),coalesce(sum(m.amount) filter(where m.move_type='gasto' and m.expense_kind='tax'),0),coalesce(sum(m.amount) filter(where m.move_type='gasto' and m.expense_kind='investment'),0) into v_sales,v_personal,v_operating,v_tax_cash,v_investment from public.moves m where m.user_id=new.user_id and m.move_date>=new.month and m.move_date<(new.month+interval '1 month')::date; select coalesce(sum(case when coalesce(m.recurrence,'oneoff')='quarterly' and ((extract(year from age(new.month,date_trunc('month',m.move_date)::date))*12+extract(month from age(new.month,date_trunc('month',m.move_date)::date))) between 0 and 2) then m.amount/3 when coalesce(m.recurrence,'oneoff')='annual' and ((extract(year from age(new.month,date_trunc('month',m.move_date)::date))*12+extract(month from age(new.month,date_trunc('month',m.move_date)::date))) between 0 and 11) then m.amount/12 when coalesce(m.recurrence,'oneoff') in ('monthly','oneoff') and date_trunc('month',m.move_date)::date=new.month then m.amount else 0 end),0) into v_tax_load from public.moves m where m.user_id=new.user_id and m.move_type='gasto' and m.expense_kind='tax' and date_trunc('month',m.move_date)::date<=new.month; select coalesce(sum(m.amount),0) into v_personal_cash from public.moves m where m.user_id=new.user_id and m.move_type='personal' and m.move_date>=new.month and m.move_date<(new.month+interval '1 month')::date and m.payroll_run_id is null and coalesce(m.notes,'') not like '%payroll_run:%' and coalesce(m.concept,'') !~ '^Nóminas gestor [0-9]{4}-[0-9]{2}$'; select v_personal_cash+coalesce(sum(p.amount),0) into v_personal_cash from public.payroll_payments p where p.user_id=new.user_id and p.paid_on>=new.month and p.paid_on<(new.month+interval '1 month')::date; new.summary:=jsonb_build_object('document_count',v_document_count,'accounting_count',v_accounting_count,'invoice_count',v_invoice_count,'ticket_count',v_ticket_count,'supplier_count',v_supplier_count,'net_total',v_purchases,'invoice_base',v_invoice_base,'invoice_vat',v_invoice_vat,'sales_total',v_sales,'purchases_total',v_purchases,'personal_total',v_personal,'operating_expense_total',v_operating,'tax_cash_total',v_tax_cash,'tax_load_total',v_tax_load,'investment_total',v_investment,'result_estimate',v_sales-v_purchases-v_personal-v_operating-v_tax_load,'personnel_cash_total',v_personal_cash,'cash_out_total',v_purchases+v_personal_cash+v_operating+v_tax_cash+v_investment,'captured_at',now()); return new; end; $function$
